import logging

logger = logging.getLogger()
logger.setLevel(logging.INFO)

# Stands in for the user table. Record u-1002 was written without an email.
USERS = {
    "u-1001": {"email": "Ana.Silva@Example.com ", "purchase_count": 3},
    "u-1002": {"email": None, "purchase_count": 12},
}


def calculate_tier(purchase_count):
    if (purchase_count or 0) >= 10:
        return "gold"
    return "standard"


def lambda_handler(event, context):
    user_id = (event or {}).get("user_id", "u-1002")
    logger.info("registering user_id=%s", user_id)
    user_data = USERS.get(user_id, {})
    email = user_data["email"].lower().strip()  # no null check
    tier = calculate_tier(user_data.get("purchase_count"))
    logger.info("registered user_id=%s tier=%s", user_id, tier)
    return {"statusCode": 200, "email": email, "tier": tier}
